const TEACHERS = {"A":"Ikbal Afan Zka","G":"Eko Mei Sugiharto, S.Pd","B":"Ambar Susetiyowati, S.Pd","H":"Bambang Muharwo, S.Pt.,M.M","C":"Galih Ade Triana, S,Pd","I":"Nur Laeli Qitfiyah, S.Pd","D":"Anggi Nur Utami, S.Pd","J":"Yulius Sutanto, S.Pd","E":"Amin Nuryanto, A.Md,Kom.","K":"Mumtazul Mahasin Al-Haqi","F":"Destio Tabah Sujarwo, S.Pd","L":"Kartiko Sugiarto, A.Md","M":"Irma Novita Sari"};


const PAGE_SIZE = 18;
let currentPage = 1;
let activeSection = 'dashboard';
let dashboardDay = 'Senin';

const $ = (id) => document.getElementById(id);
const els = {
  search: $('globalSearch'),
  day: $('dayFilter'),
  class: $('classFilter'),
  teacher: $('teacherFilter'),
  time: $('timeFilter'),
  subject: $('subjectFilter'),
  scheduleBody: $('scheduleBody'),
  resultCount: $('resultCount'),
  pagination: $('pagination'),
  activeFilters: $('activeFilters'),
  empty: $('emptyState'),
  teacherGrid: $('teacherGrid'),
  classGrid: $('classGrid'),
  subjectGrid: $('subjectGrid'),
  todayList: $('todayList'),
  dashboardDay: $('dashboardDay'),
  mobileMenu: $('mobileMenu'),
  sidebar: $('sidebar'),
  overlay: $('overlay'),
  clearSearch: $('clearSearch')
};

const DAY_ORDER = ['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
const CLASS_ORDER = ['X MP','X DKV','X TSM','XI MP','XI DKV','XI TSM','XII MP','XII DKV','XII TSM'];

function normalize(value) {
  return String(value ?? '').toLocaleLowerCase('id-ID').trim();
}

function escapeHTML(value) {
  return String(value ?? '')
    .replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')
    .replaceAll('"','&quot;').replaceAll("'",'&#039;');
}

function unique(values, order = []) {
  const list = [...new Set(values.filter(Boolean))];
  return list.sort((a,b) => {
    const ai = order.indexOf(a), bi = order.indexOf(b);
    if (ai !== -1 || bi !== -1) return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
    return a.localeCompare(b, 'id');
  });
}

function fillSelect(select, values, order = []) {
  if (!select) return;
  const placeholder = select.firstElementChild;
  select.innerHTML = '';
  if (placeholder) select.appendChild(placeholder);
  unique(values, order).forEach(value => {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = value;
    select.appendChild(option);
  });
}

function setupFilters() {
  fillSelect(els.day, SCHEDULE.map(x => x.day), DAY_ORDER);
  fillSelect(els.class, SCHEDULE.map(x => x.class), CLASS_ORDER);
  fillSelect(els.teacher, SCHEDULE.map(x => x.teacher));
  fillSelect(els.time, SCHEDULE.map(x => x.time));
  fillSelect(els.subject, SCHEDULE.map(x => x.subject));
}

function filteredSchedule() {
  const query = normalize(els.search?.value);
  return SCHEDULE.filter(item => {
    const haystack = normalize([item.day,item.time,item.period,item.class,item.subject,item.teacher,item.teacherCode].join(' '));
    return (!query || haystack.includes(query))
      && (!els.day?.value || item.day === els.day.value)
      && (!els.class?.value || item.class === els.class.value)
      && (!els.teacher?.value || item.teacher === els.teacher.value)
      && (!els.time?.value || item.time === els.time.value)
      && (!els.subject?.value || item.subject === els.subject.value);
  });
}

function scheduleCard(item) {
  return `
    <article class="schedule-card">
      <div class="schedule-time">
        <span>${escapeHTML(item.time)}</span>
        <small>Jam ke-${escapeHTML(item.period)}</small>
      </div>
      <div class="schedule-main">
        <div class="schedule-meta"><span>${escapeHTML(item.day)}</span><b>${escapeHTML(item.class)}</b></div>
        <h3>${escapeHTML(item.subject)}</h3>
        <p>${item.teacher ? `${escapeHTML(item.teacher)} <em>${escapeHTML(item.teacherCode || '')}</em>` : 'Guru belum ditentukan'}</p>
      </div>
      <span class="schedule-arrow">↗</span>
    </article>`;
}

function renderDashboard() {
  const items = SCHEDULE.filter(x => x.day === dashboardDay);
  els.dashboardDay.textContent = dashboardDay;
  els.todayList.innerHTML = items.slice(0, 9).map(scheduleCard).join('');
  if ($('todayCount')) $('todayCount').textContent = `${items.length} entri`;
  $('dashboardMore').onclick = () => {
    els.day.value = dashboardDay;
    activateSection('jadwal');
    renderSchedule();
  };
}

function renderSchedule() {
  const items = filteredSchedule();
  const pages = Math.max(1, Math.ceil(items.length / PAGE_SIZE));
  if (currentPage > pages) currentPage = pages;
  const start = (currentPage - 1) * PAGE_SIZE;
  const pageItems = items.slice(start, start + PAGE_SIZE);

  els.resultCount.textContent = `${items.length} jadwal ditemukan`;
  els.scheduleBody.innerHTML = pageItems.map(scheduleCard).join('');
  els.empty.hidden = items.length !== 0;
  els.pagination.innerHTML = '';

  if (pages > 1) {
    const addPage = (label, page, active=false) => {
      const b = document.createElement('button');
      b.className = `page-button${active ? ' active' : ''}`;
      b.textContent = label;
      b.onclick = () => { currentPage = page; renderSchedule(); window.scrollTo({top:0,behavior:'smooth'}); };
      els.pagination.appendChild(b);
    };
    if (currentPage > 1) addPage('←', currentPage-1);
    for (let p=1;p<=pages;p++) {
      if (pages > 8 && p > 2 && p < pages-1 && Math.abs(p-currentPage)>1) {
        if (p===3 || p===pages-2) {
          const dots=document.createElement('span'); dots.className='page-dots'; dots.textContent='…'; els.pagination.appendChild(dots);
        }
        continue;
      }
      addPage(String(p),p,p===currentPage);
    }
    if (currentPage < pages) addPage('→', currentPage+1);
  }

  const active = [];
  if (els.search.value) active.push(`Cari: ${els.search.value}`);
  if (els.day.value) active.push(`Hari: ${els.day.value}`);
  if (els.class.value) active.push(`Kelas: ${els.class.value}`);
  if (els.teacher.value) active.push(`Guru: ${els.teacher.value}`);
  if (els.time.value) active.push(`Jam: ${els.time.value}`);
  if (els.subject.value) active.push(`Mapel: ${els.subject.value}`);
  els.activeFilters.innerHTML = active.map(x=>`<span>${escapeHTML(x)}</span>`).join('');
}

function renderTeachers() {
  const entries = Object.entries(TEACHERS).sort(([a],[b])=>a.localeCompare(b));
  els.teacherGrid.innerHTML = entries.map(([code,name])=>`<article class="directory-card"><span class="directory-code">${escapeHTML(code)}</span><h3>${escapeHTML(name)}</h3><p>${SCHEDULE.filter(x=>x.teacherCode===code).length} jadwal</p></article>`).join('');
  $('teacherTotal').textContent = entries.length;
}

function renderClasses() {
  els.classGrid.innerHTML = CLASS_ORDER.map(cls=>`<button class="class-card" data-class="${escapeHTML(cls)}"><span>${escapeHTML(cls.split(' ')[0])}</span><strong>${escapeHTML(cls.split(' ').slice(1).join(' '))}</strong><small>${SCHEDULE.filter(x=>x.class===cls).length} jadwal</small></button>`).join('');
  els.classGrid.querySelectorAll('[data-class]').forEach(btn=>btn.onclick=()=>{ els.class.value=btn.dataset.class; activateSection('jadwal'); currentPage=1; renderSchedule(); });
  $('classTotal').textContent = CLASS_ORDER.length;
}

function renderSubjects() {
  const subjects = unique(SCHEDULE.map(x=>x.subject));
  els.subjectGrid.innerHTML = subjects.map((subject,i)=>`<button class="subject-card" data-subject="${escapeHTML(subject)}"><span>${String(i+1).padStart(2,'0')}</span><strong>${escapeHTML(subject)}</strong><small>${SCHEDULE.filter(x=>x.subject===subject).length} jadwal</small></button>`).join('');
  els.subjectGrid.querySelectorAll('[data-subject]').forEach(btn=>btn.onclick=()=>{ els.subject.value=btn.dataset.subject; activateSection('jadwal'); currentPage=1; renderSchedule(); });
  $('subjectTotal').textContent = subjects.length;
}

function activateSection(section) {
  activeSection = section;
  document.querySelectorAll('.page-section').forEach(s=>s.classList.toggle('active', s.id===`page-${section}`));
  document.querySelectorAll('.nav-item').forEach(a=>a.classList.toggle('active', a.dataset.section===section));
  const titles = {dashboard:'Dashboard',jadwal:'Jadwal Pelajaran',kelas:'Daftar Kelas',guru:'Direktori Guru',mapel:'Mata Pelajaran'};
  $('pageTitle').textContent = titles[section] || 'Dashboard';
  closeSidebar();
  if (section==='jadwal') renderSchedule();
  if (section==='guru') renderTeachers();
  if (section==='kelas') renderClasses();
  if (section==='mapel') renderSubjects();
}

function resetFilters() {
  els.search.value=''; els.day.value=''; els.class.value=''; els.teacher.value=''; els.time.value=''; els.subject.value=''; currentPage=1; renderSchedule();
}

function openSidebar() { els.sidebar.classList.add('open'); els.overlay.classList.add('show'); }
function closeSidebar() { els.sidebar.classList.remove('open'); els.overlay.classList.remove('show'); }

function init() {
  setupFilters();
  renderDashboard(); renderTeachers(); renderClasses(); renderSubjects(); renderSchedule();

  document.querySelectorAll('.nav-item').forEach(item=>item.addEventListener('click',e=>{e.preventDefault();activateSection(item.dataset.section);}));
  document.querySelector('.brand[data-section]')?.addEventListener('click',e=>{e.preventDefault();activateSection('dashboard');});
  [els.search,els.day,els.class,els.teacher,els.time,els.subject].forEach(el=>{
    el.addEventListener('input',()=>{currentPage=1;renderSchedule();});
    el.addEventListener('change',()=>{currentPage=1;renderSchedule();});
  });
  els.clearSearch?.addEventListener('click',()=>{els.search.value='';currentPage=1;renderSchedule();els.search.focus();});
  $('resetFilters')?.addEventListener('click',resetFilters);
  const openSearch = () => { activateSection('jadwal'); setTimeout(()=>els.search?.focus(), 0); };
  $('quickSearch')?.addEventListener('click', openSearch);
  $('quickSearch2')?.addEventListener('click', openSearch);
  $('quickClasses')?.addEventListener('click',()=>activateSection('kelas'));
  $('quickTeachers')?.addEventListener('click',()=>activateSection('guru'));
  $('quickSubjects')?.addEventListener('click',()=>activateSection('mapel'));
  els.mobileMenu?.addEventListener('click',openSidebar);
  $('closeSidebar')?.addEventListener('click',closeSidebar);
  els.overlay?.addEventListener('click',closeSidebar);
  document.querySelectorAll('[data-day]').forEach(btn=>btn.addEventListener('click',()=>{dashboardDay=btn.dataset.day;renderDashboard();document.querySelectorAll('[data-day]').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');}));
}

document.addEventListener('DOMContentLoaded', init);
